/**
 * Returns the datacenter code for a given realm and region.
 * Prevents cross-region collisions (e.g. US:hyjal -> LA, EU:hyjal -> EU-FRA).
 */
function getSubRegion(serverSlug, region = 'US') {
  const reg = String(region || 'US').trim().toUpperCase();
  const clean = String(serverSlug || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  
  // 1. Direct [REGION:realm] lookup
  const exactKey = `${reg}:${clean}`;
  if (REALM_SUBREGION_MAP[exactKey]) {
    return REALM_SUBREGION_MAP[exactKey];
  }

  // 2. Fallback by region if realm is unlisted or custom
  if (reg === 'EU') return 'EU-Oth';
  if (reg === 'KR') return 'KR';
  if (reg === 'TW') return 'TW';
  if (reg === 'US' || reg === 'NA') return 'CHI'; // Default North America to Chicago
  return 'Oth';
}

module.exports = {
  REALM_SUBREGION_MAP,
  getSubRegion,
};
